(() => {
  const marker = document.getElementById("stui-experiment-package");
  const pkg = marker ? JSON.parse(marker.textContent || "{}") : null;
  const root = document.getElementById("stui-experiment-root");
  if (!pkg || !root) return;
  const state = { transpose: Boolean(pkg.behavior && pkg.behavior.transpose), hidden: {} };
  (pkg.behavior.sections || []).forEach((section) => { state.hidden[section.id] = section.visible === false; });
  function render() {
    const columns = (pkg.dataContract.columns || []).filter((column) => !(pkg.presentation.hiddenColumnIds || []).includes(column.id));
    const rows = pkg.fixture.rows || [];
    const sections = (pkg.behavior.sections || []).map((section) => {
      const hidden = state.hidden[section.id] === true;
      return '<section data-section-id="' + section.id + '" data-hidden="' + hidden + '"><button type="button" data-toggle="' + section.id + '">' + (hidden ? "Näytä" : "Piilota") + " " + section.label + '</button>' + (hidden ? "" : "<p>" + section.label + "</p>") + "</section>";
    }).join("");
    const head = state.transpose
      ? "<tr><th>Sarake</th>" + rows.map((row) => "<th data-row-id='" + row.id + "'>" + row.id + "</th>").join("") + "</tr>"
      : "<tr>" + columns.map((column) => "<th data-column-id='" + column.id + "'>" + column.label + "</th>").join("") + "</tr>";
    const body = state.transpose
      ? columns.map((column) => "<tr data-column-id='" + column.id + "'><th>" + column.label + "</th>" + rows.map((row) => "<td data-row-id='" + row.id + "' data-column-id='" + column.id + "'>" + (row.values[column.id] || "") + "</td>").join("") + "</tr>").join("")
      : rows.map((row) => "<tr data-row-id='" + row.id + "'>" + columns.map((column) => "<td data-column-id='" + column.id + "'>" + (row.values[column.id] || "") + "</td>").join("") + "</tr>").join("");
    root.innerHTML = '<p data-stui-id="' + pkg.stuiId + '" data-model-version="' + pkg.modelVersion + '">' + pkg.stuiId + " " + pkg.modelVersion + '</p>' + sections + '<button type="button" id="transpose">Transponoi</button><table>' + head + body + "</table>";
  }
  render();
})();
